locals {
  ip_whitelist = {
    qa = [
      "34.23.50.140",
    ]
    staging = [
      "35.196.126.133",
    ]
    prod = [
      "34.74.192.228",
    ]
    sha = [
      "35.185.50.62",
    ]
    sec = [
      "35.227.65.152",
    ]
  }
}

module "cloud_armor" {
  source             = "git::ssh://git@github.com/liftitapp/tf-modules.git//waf"
  policy_name        = "liftit-waf-${local.environment}"
  policy_description = "Política de seguridad WAF Liftit"
  rules = {
    "1000" = {
      action         = "allow"
      description    = "Permitir IPs de confianza"
      preview        = false
      versioned_expr = "SRC_IPS_V1"
      src_ip_ranges  = local.ip_whitelist[terraform.workspace]
    },
    "1010" = {
      action      = "deny(403)"
      description = "Bloquea ciertos user-agents"
      preview     = true
      expr        = "'[AhrefsBot,Baiduspider,Screaming Frog SEO Spider,SemrushBot,YandexBot,spbot,python-request,panscient.com,BlackWidow,360Spider,sqlmap,SurveyBot,BLEXBot,masscan,SucuriScan,DirBuster,Arachni,W3C_Validator,Fetchbot,ZoominfoBot,NetcraftSurveyAgent,CensysInspect,ExpiredDomainsBot,Xenu,LinkChecker,DatanyzeBot,zgrab,CCBot,oBot,Custom-AsyncHttpClient]'.contains(request.headers['user-agent'])"
    },
    "1020" = {
      action         = "deny(403)"
      description    = "Permitir GoogleStackdriverMonitoring-UptimeChecks"
      preview        = true
      versioned_expr = ""
      expr           = "request.headers['user-agent'].matches('(?i:GoogleStackdriverMonitoring-UptimeChecks)')"
    },
    "1030" = {
      action         = "deny(403)"
      description    = "Inserción de SQL (En sincronización con sqli-v33-stable)"
      preview        = true
      versioned_expr = ""
      expr           = "evaluatePreconfiguredExpr('sqli-v33-stable')"
    },
    "1040" = {
      action         = "deny(403)"
      description    = "Cross Site Scripting (En sincronización con xss-v33-stable)"
      preview        = true
      versioned_expr = ""
      expr           = "evaluatePreconfiguredExpr('xss-v33-stable')"
    },
    "1050" = {
      action         = "deny(403)"
      description    = "Inclusión de Archivos Locales (En sincronización con lfi-v33-stable)"
      preview        = true
      versioned_expr = ""
      expr           = "evaluatePreconfiguredExpr('lfi-v33-stable')"
    },
    "1060" = {
      action         = "deny(403)"
      description    = "Ejecución de Código Remoto (En sincronización con rce-v33-stable)"
      preview        = true
      versioned_expr = ""
      expr           = "evaluatePreconfiguredExpr('rce-v33-stable')"
    },
    "1070" = {
      action         = "deny(403)"
      description    = "Inclusión de Archivos Remotos (En sincronización con rfi-v33-stable)"
      preview        = true
      versioned_expr = ""
      expr           = "evaluatePreconfiguredExpr('rfi-v33-stable')"
    },
    "1080" = {
      action         = "deny(403)"
      description    = "Aplicación de Métodos (En sincronización con methodenforcement-v33-stable)"
      preview        = true
      versioned_expr = ""
      expr           = "evaluatePreconfiguredExpr('methodenforcement-v33-stable')"
    },
    "1090" = {
      action         = "deny(403)"
      description    = "Detección de Scanner (En sincronización con scannerdetection-v33-stable)"
      preview        = true
      versioned_expr = ""
      expr           = "evaluatePreconfiguredExpr('scannerdetection-v33-stable')"
    },
    "1100" = {
      action         = "deny(403)"
      description    = "Ataque de protocolo (En sincronización con protocolattack-v33-stable)"
      preview        = true
      versioned_expr = ""
      expr           = "evaluatePreconfiguredExpr('protocolattack-v33-stable')"
    },
    "1110" = {
      action         = "deny(403)"
      description    = "PHP (En sincronización con php-v33-stable)"
      preview        = true
      versioned_expr = ""
      expr           = "evaluatePreconfiguredExpr('php-v33-stable')"
    },
    "1120" = {
      action         = "deny(403)"
      description    = "Corrección de la Sesión (En sincronización con sessionfixation-v33-stable)"
      preview        = true
      versioned_expr = ""
      expr           = "evaluatePreconfiguredExpr('sessionfixation-v33-stable')"
    },
    "1130" = {
      action         = "deny(403)"
      description    = "Ataque de Java (En sincronización con java-v33-stable)"
      preview        = true
      versioned_expr = ""
      expr           = "evaluatePreconfiguredExpr('java-v33-stable')"
    },
    "1140" = {
      action         = "deny(403)"
      description    = "Ataque de NodeJS (En sincronización con nodejs-v33-stable)"
      preview        = true
      versioned_expr = ""
      expr           = "evaluatePreconfiguredExpr('nodejs-v33-stable')"
    },
    "1150" = {
      action         = "deny(403)"
      description    = "CVE y otras Vulnerabilidades (En sincronización con cve-canary)"
      preview        = true
      versioned_expr = ""
      expr           = "evaluatePreconfiguredExpr('cve-canary')"
    },
    "1160" = {
      action         = "deny(403)"
      description    = "SQLi en JSON (En sincronización con sqli en JSON)"
      preview        = true
      versioned_expr = ""
      expr           = "evaluatePreconfiguredWaf('json-sqli-canary', {'sensitivity':0, 'opt_in_rule_ids': ['owasp-crs-id942550-sqli']})"
    }
    "1170" = {
      action         = "rate_based_ban"
      description    = "Rate limit por IP"
      preview        = true
      versioned_expr = "SRC_IPS_V1"
      src_ip_ranges  = ["*"]
      rate_limit_options = {
        rate_limit_threshold = {
          count        = 1000
          interval_sec = 60
        }
        ban_duration_sec = 300
        ban_threshold = {
          count        = 2000
          interval_sec = 60
        }
      }
    }

  }
}

